from datetime import date
from decimal import Decimal
def total(entries):
    return sum((e.amount for e in entries),Decimal('0'))
def _coerce_bound(value):
    if value is None:
        return None
    if isinstance(value, date):
        return value
    return date.fromisoformat(value)
def totals_by_currency(entries, start=None, end=None, include_pending=False):
    start = _coerce_bound(start)
    end = _coerce_bound(end)
    if start is not None and end is not None and start > end:
        raise ValueError('start must not be after end')
    totals = {}
    for entry in entries:
        if not include_pending and entry.status != 'posted':
            continue
        if start is not None and entry.day < start:
            continue
        if end is not None and entry.day > end:
            continue
        totals[entry.currency] = totals.get(entry.currency, Decimal('0')) + entry.amount
    return totals

import json
from .parser import parse_csv
from .summary import total, totals_by_currency
def render_report(text, *, by_currency=False, start=None, end=None):
    if by_currency:
        entries = parse_csv(text)
        totals = totals_by_currency(entries, start=start, end=end, include_pending=True)
        return json.dumps({'totals': {currency: format(amount, '.2f') for currency, amount in sorted(totals.items())}}, sort_keys=True)
    return json.dumps({'total':format(total(parse_csv(text)),'.2f')},sort_keys=True)

